import { useState } from 'react';
import { Menu, X } from 'lucide-react';
import Hero from './components/Hero';
import Features from './components/Features';
import Pricing from './components/Pricing';
import Faq from './components/Faq';

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const links = [
    { label: 'Features', href: '#features' },
    { label: 'Pricing', href: '#pricing' },
    { label: 'FAQ', href: '#faq' },
  ];
  return (
    <div className="min-h-screen bg-white text-slate-900">
      <header className="sticky top-0 z-50 bg-white/85 backdrop-blur-xl border-b border-slate-200/70">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <a href="#top" className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-xl bg-gradient-to-br from-indigo-600 to-violet-600 inline-block" />
            <span className="font-extrabold text-lg tracking-tight">Sterling & Cole</span>
          </a>
          <nav className="hidden md:flex items-center gap-8 text-sm font-medium text-slate-600">
            {links.map(l => <a key={l.href} href={l.href} className="hover:text-slate-900 transition-colors">{l.label}</a>)}
          </nav>
          <div className="hidden md:flex items-center gap-3">
            <a href="#cta" className="px-4 py-2 rounded-xl bg-slate-900 text-white text-sm font-semibold hover:bg-slate-700 transition-colors">Get started</a>
          </div>
          <button className="md:hidden p-2" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menu">
            {menuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
          </button>
        </div>
        {menuOpen && (
          <div className="md:hidden border-t border-slate-200 bg-white px-6 py-4 space-y-3">
            {links.map(l => <a key={l.href} href={l.href} onClick={() => setMenuOpen(false)} className="block font-medium text-slate-700">{l.label}</a>)}
          </div>
        )}
      </header>
      <main id="top">
      <Hero />
      <Features />
      <Pricing />
      <Faq />
      </main>
      <footer className="border-t border-slate-200 py-10 text-center text-sm text-slate-500">
        <span className="font-bold text-slate-700">Sterling & Cole</span> &copy; 2026. All rights reserved.
      </footer>
    </div>
  );
}

import React, { useState } from 'react';
import { ChevronRight, Sparkles, CheckCircle2, Info, AlertCircle, User, ShieldCheck, ShieldAlert } from 'lucide-react';

const FAQ_DATA = [
  {
    id: 1,
    question: "Do you handle international legal matters?",
    answer:
      "Yes, our firm has a dedicated international division specializing in cross-border transactions, intellectual property, and international trade disputes. We ensure seamless coordination across jurisdictions.",
    status: "active",
    icon: Sparkles
  },
  {
    id: 2,
    question: "How long does a typical consultation take?",
    answer:
      "We aim to provide comprehensive consultations within 30 minutes. However, the duration can vary based on the complexity of the case. Longer consultations are scheduled upon request.",
    status: "active",
    icon: Sparkles
  },
  {
    id: 3,
    question: "What is your contingency fee structure?",
    answer:
      "In civil litigation and large corporate cases, we operate on a contingency fee basis. A detailed fee agreement is provided during the initial consultation.",
    status: "active",
    icon: Sparkles
  },
  {
    id: 4,
    question: "Are your attorneys licensed in my state?",
    answer:
      "Our network includes licensed attorneys in all 50 states. For multi-state and international matters, we collaborate with pre-vetted partners ensuring jurisdictional compliance.",
    status: "active",
    icon: Sparkles
  },
  {
    id: 5,
    question: "How do I schedule a free consultation?",
    answer:
      "Simply fill out our online intake form or reach out directly to our client relations team. They will guide you through the scheduling process and prepare you for your initial meeting.",
    status: "active",
    icon: Sparkles
  }
];

export default function Faq() {
  const [expanded, setExpanded] = useState(null);

  return (
    <div className="w-full max-w-4xl mx-auto p-6 sm:p-8 bg-slate-950 text-slate-100 font-sans">
      <div className="relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 shadow-2xl transition-all duration-300">

        {/* Decorative Gradient Header */}
        <div className="absolute top-0 left-0 right-0 h-4 bg-gradient-to-r from-indigo-500 via-purple-600 to-pink-600 opacity-50" />

        {/* Main Content */}
        <div className="p-6 sm:p-8 pb-12 flex flex-col space-y-6">

          {/* Header Section */}
          <div className="flex items-start justify-between pb-6 border-b border-white/10">
            <div>
              <h2 className="text-2xl font-bold tracking-tight text-slate-100 flex items-center gap-2">
                <Info className="w-5 h-5 text-indigo-400 animate-pulse" /> Frequently Asked Questions
              </h2>
              <p className="text-slate-400 text-sm mt-1">
                Get answers to common queries about our legal services and firm policies.
              </p>
            </div>
            <button className="self-start text-slate-400 hover:text-white border border-slate-700 rounded-lg px-3 py-1.5 shadow-inner transition-colors duration-200">
              <a href="#contact" className="flex items-center gap-1">
                <span>Contact Us</span>
                <Sparkles className="w-4 h-4" />
              </a>
            </button>
          </div>

          {/* Accordion Items */}
          <div className="space-y-6">
            {FAQ_DATA.map((faq) => (
              <div key={faq.id} className="group relative rounded-xl bg-white/5 border border-white/10 p-6 backdrop-blur-xl transition-all duration-300 hover:border-indigo-500/50 hover:shadow-indigo-500/10 active:scale-[0.98]">
                {/* Top Decorative Border */}
                <div className="absolute -top-0.5 left-6 right-6 border-t border-white/10" />

                {/* Toggle Icon */}
                <div className="absolute top-6 right-6 flex items-center gap-1.5 text-slate-400 group-hover:text-slate-200 transition-colors duration-200">
                  {expanded === faq.id ? <ChevronRight className="w-4 h-4" /> : <ChevronRight className="w-4 h-4 text-indigo-400" />}
                </div>

                {/* Content Area */}
                <div className="pt-12 pb-6 text-slate-400 transition-all duration-300 group-ativo:pt-4 group-ativo:pb-4">
                  <h3 className="text-lg font-semibold text-slate-100 mb-2 flex items-center gap-1">
                    {faq.icon ? <faq.icon className="w-5 h-5 text-indigo-400" /> : null}
                    {faq.question}
                  </h3>
                  <p className="text-sm text-slate-400">{faq.answer}</p>
                </div>

                {/* Border for expanded state */}
                {expanded === faq.id && (
                  <div className="absolute -top-0.5 right-6 left-6 border-t border-white/10" />
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Bottom Decorative Accent */}
        <div className="absolute bottom-0 left-0 right-0 h-4 bg-gradient-to-r from-purple-600 via-pink-600 to-rose-600 opacity-10" />
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Sparkles, ShieldCheck, ShieldAlert, Users, ChevronRight, X } from 'lucide-react';

const features = [
  {
    id: 1,
    name: 'Comprehensive Legal Solutions',
    description: 'Our team specializes in corporate, intellectual property, and litigation matters.',
    icon: Sparkles,
    color: 'from-indigo-500 to-purple-600',
  },
  {
    id: 2,
    name: 'Global Reach',
    description: 'With offices in major cities, we offer seamless legal representation across borders.',
    icon: ShieldCheck,
    color: 'from-emerald-400 to-teal-500',
  },
  {
    id: 3,
    name: 'Client-Centric Approach',
    description: 'We prioritize transparency and clear communication throughout the legal process.',
    icon: ShieldAlert,
    color: 'from-amber-400 to-rose-500',
  },
  {
    id: 4,
    name: '24/7 Availability',
    description: 'Our dedicated support team is always ready to assist you with urgent matters.',
    icon: Users,
    color: 'from-blue-400 to-cyan-500',
  },
];

export default function Features() {
  const [isHovered, setIsHovered] = useState(null);
  const [isOpen, setIsOpen] = useState(1);

  return (
    <div className="w-full bg-slate-900 p-4 sm:p-6 lg:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-white/5 border border-white/10 text-indigo-400 mb-4">
            <Sparkles className="w-6 h-6" />
          </div>
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold tracking-tight text-slate-100 mb-4">
            Tailored Legal Expertise for Your Business
          </h2>
          <p className="text-slate-400 max-w-md mx-auto">
            Sterling & Cole offers bespoke legal strategies that align with your industry's unique challenges.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {features.map((feat) => {
            const active = isOpen === feat.id;
            const borderColor = active ? 'from-indigo-500/40 to-purple-500/40' : 'from-slate-500/30 to-slate-900/30';

            return (
              <div
                key={feat.id}
                className="relative rounded-2xl bg-white/5 border border-white/10 backdrop-blur-xl p-6 transition-all duration-300 hover:scale-[1.02] hover:border-white/20 hover:shadow-2xl group"
                style={{ boxShadow: '0 10px 20px rgba(0,0,0,0.1)' }}
                onMouseEnter={() => setIsHovered(feat.id)}
                onMouseLeave={() => setIsHovered(null)}
              >
                <div className="absolute -inset-1 rounded-2xl bg-white/10 border border-white/5 group-hover:bg-white/20" />
                <div className="relative flex flex-col justify-between">
                  <div className="flex items-start justify-between mb-6">
                    <div className="flex items-center space-x-2">
                      <feat.icon className="w-5 h-5 text-white/40 group-hover:text-white" />
                      <h3 className="text-lg font-semibold text-slate-100 group-hover:text-slate-100">{feat.name}</h3>
                    </div>
                    {active && (
                      <button
                        onClick={() => setIsOpen(null)}
                        className="p-2 rounded-xl bg-white/5 text-slate-400 hover:text-slate-200 transition-colors duration-200"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                  <p className="text-slate-400">{feat.description}</p>
                </div>
                {active && (
                  <div className="absolute inset-0 bg-white/5 border border-white/10 rounded-2xl backdrop-blur-xl flex items-center justify-center p-6">
                    <div className="max-w-md">
                      <h4 className="text-lg font-semibold text-slate-100">Explore {feat.name}</h4>
                      <p className="text-sm text-slate-400 mt-2">Discover how our specialized expertise drives success.</p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Sparkles, CheckCircle2, DollarSign, ShieldCheck, AlertCircle, X, ArrowRight, ChevronRight, BarChart3 } from 'lucide-react';

const tiers = [
  {
    name: 'Standard',
    price: '149/mo',
    features: ['Unlimited Basic Cases', '2 Dependent Users', 'Weekly Progress Reports'],
    highlight: false,
    selected: false,
    max: 2,
    active: true,
  },
  {
    name: 'Professional',
    price: '249/mo',
    features: ['Enterprise Tier Access', 'Unlimited Users', 'Advanced Analytics & Reporting'],
    highlight: true,
    selected: false,
    max: Infinity,
    active: true,
  },
  {
    name: 'Enterprise',
    price: '499/mo',
    features: ['Customizable Templates', 'Priority Support', 'Dedicated Account Manager'],
    highlight: false,
    selected: false,
    max: Infinity,
    active: true,
  },
];

export default function Pricing() {
  const [activeTier, setActiveTier] = useState('Professional');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const toggleTier = (id) => {
    setActiveTier(id);
  };

  const handleSubscribe = () => {
    setIsModalOpen(true);
  };

  const getActiveClass = (id) => {
    return activeTier === id ? 'bg-indigo-600/20 text-indigo-400 border border-indigo-600/30' : 'hover:bg-white/5';
  };

  return (
    <div className="w-full max-w-7xl mx-auto p-4 sm:p-6 lg:p-8 bg-slate-950 text-slate-100">
      <div className="mb-12 lg:mb-16">
        <div className="relative overflow-hidden rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10 shadow-2xl transition-all duration-300 hover:shadow-indigo-500/10">
          <div className="relative p-6 sm:p-8 bg-white/10 border-b border-white/5 flex items-start justify-between gap-6">
            <div className="flex items-center gap-3">
              <div className="p-3 rounded-xl bg-indigo-500/10 text-indigo-400 shadow-inner"><Sparkles size={18} /></div>
              <div>
                <h2 className="text-xl font-semibold tracking-tight text-slate-100">Pricing & Billing</h2>
                <p className="text-sm text-slate-400">Transparent rates for seamless growth.</p>
              </div>
            </div>
            <div className="w-full bg-white/5 rounded-xl p-3 text-center shadow-inner">
              <button
                onClick={handleSubscribe}
                className="inline-flex justify-center items-center gap-2 px-4 py-2 rounded-full text-sm font-medium text-white bg-indigo-600/20 border border-indigo-600/30 hover:bg-indigo-600/30 active:scale-95 transition-all duration-200"
              >
                <BarChart3 className="w-4 h-4" /> Free Consultation
              </button>
            </div>
          </div>
          <div className="relative p-6 sm:p-8">
            {tiers.map((tier) => {
              const isHovered = tier.name === activeTier;
              return (
                <div
                  key={tier.name}
                  onMouseEnter={() => toggleTier(tier.name)}
                  onMouseLeave={() => toggleTier(tier.name)}
                  className={`group relative rounded-2xl p-6 sm:p-8 bg-white/5 border border-white/5 hover:scale-[1.015] transition-transform duration-300 hover:border-white/10 hover:bg-white/10 ${
                    tier.name === activeTier ? 'border-white bg-white/10' : ''
                  }`}
                >
                  <div className="flex flex-col gap-3 sm:gap-4">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-white/20 text-white shadow-inner"><DollarSign size={16} /></div>
                        <h3 className="text-xl font-semibold text-slate-100">{tier.name}</h3>
                      </div>
                      <div className="group-hover:flex group-hover:items-start hidden gap-3">
                        <span className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-medium bg-indigo-600/10 text-indigo-400 border border-indigo-600/20">
                          <Sparkles className="w-3 h-3" /> Popular
                        </span>
                        <div className="inline-flex items-center gap-1 px-3 py-1.5 rounded-xl bg-indigo-600/10 text-indigo-400 border border-indigo-600/20">
                          <CheckCircle2 className="w-3 h-3" /> Active
                        </div>
                      </div>
                    </div>
                    <div className="flex-1">
                      <ul className="flex flex-col gap-3 sm:gap-4">
                        {tier.features.map((feature) => (
                          <li key={feature} className="flex items-center justify-between gap-4 text-slate-400">
                            <div className="flex items-center gap-2">
                              <CheckCircle2 className="w-3 h-3 text-emerald-400 group-hover:text-emerald-300" />
                              <span>{feature}</span>
                            </div>
                            <div className="flex items-center gap-2">
                              {tier.max === Infinity ? (
                                <span className="text-slate-400">Unlimited</span>
                              ) : (
                                <span className="text-slate-400">{tier.max}</span>
                              )}
                            </div>
                          </li>
                        ))}
                      </ul>
                      <button
                        onClick={() => toggleTier(tier.name)}
                        className={`mt-8 w-full rounded-xl bg-indigo-600/10 text-indigo-400 border border-indigo-600/20 hover:bg-indigo-600/20 py-3 text-center font-semibold transition-all duration-200 ${
                          activeTier === tier.name ? 'bg-indigo-600/20 text-indigo-400 border-indigo-600/30' : ''
                        }`}
                      >
                        {activeTier === tier.name ? 'You are on this plan' : 'Select'}
                      </button>
                    </div>
                  </div>
                  {tier.name === activeTier && (
                    <div className="absolute -bottom-24 left-1/2 -translate-x-1/2 w-96 rounded-xl bg-white/10 p-6 backdrop-blur-xl border border-white/10 animate-fade-in">
                      <div className="flex items-center justify-between gap-4">
                        <div className="flex items-center gap-2 text-sm">
                          <ShieldCheck className="w-4 h-4 text-emerald-400" /> <span>Your current tier includes:</span>
                        </div>
                        <button
                          onClick={() => toggleTier('Professional')}
                          className="inline-flex items-center gap-1.5 rounded-full bg-white/10 px-3 py-1.5 text-sm text-slate-400 transition-colors hover:text-slate-200"
                        >
                          <ArrowRight className="w-3 h-3" /> Upgrade
                        </button>
                      </div>
                      <ul className="mt-4 flex flex-col gap-2 text-slate-400">
                        {tier.features.map((feature) => (
                          <li key={feature}>
                            <span className="text-slate-300">{feature}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-fade-in-out">
          <div className="w-full max-w-md overflow-hidden rounded-2xl bg-slate-900/90 backdrop-blur-xl border border-white/10 p-6 shadow-2xl transition-all duration-300">
            <div className="flex items-start justify-between pb-4 pt-5 px-6 border-b border-white/10">
              <div>
                <h2 className="text-lg font-semibold text-slate-100">Select Your Tier</h2>
                <p className="text-xs text-slate-400">Configure billing details and start your trial.</p>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                className="text-slate-400 hover:text-slate-200"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-4 py-6 px-6">
              {tiers.map((tier) => {
                const { name, price, active } = tier;
                return (
                  <button
                    key={name}
                    onClick={() => toggleTier(name)}
                    className={`w-full rounded-xl p-4 transition-all duration-200 hover:scale-[1.015] ${
                      active ? 'bg-indigo-600/10 text-indigo-400 border-indigo-600/20' : 'bg-slate-900 border-slate-800'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-3">
                      <div className="flex items-center gap-2">
                        <div className="p-2 rounded-xl bg-white/5 text-white"><DollarSign size={16} /></div>
                        <span>{price}</span>
                      </div>
                      <span className="text-sm font-semibold text-slate-300">{name}</span>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="flex items-center justify-end p-6 space-x-2">
              <button
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium text-slate-400 hover:text-slate-200 border border-slate-800 rounded-lg transition-all"
              >
                Cancel
              </button>
              <button
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium bg-indigo-600/10 text-indigo-400 border border-indigo-600/20 hover:bg-indigo-600/20 rounded-lg transition-all"
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

